/* @lc app=leetcode id=2791 lang=kotlin */ class Solution { fun countPalindromePaths(parent: List<Int>, s: String): Long = parent.indices.groupBy { parent[it] }.let { g -> IntArray(parent.size).let { mk -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].orEmpty().onEach { v -> mk[v] = mk[u] xor (1 shl (s[v] - 'a')) } }.takeIf { it.isNotEmpty() } }.flatten().fold(HashMap<Int, Int>() to 0L) { (cnt, r), v -> (r + (cnt[mk[v]] ?: 0) + (0 until 26).sumOf { cnt[mk[v] xor (1 shl it)] ?: 0 }).let { r2 -> cnt.merge(mk[v], 1) { a, b -> a + b }.let { cnt to r2 } } }.second } } }